FunctionCall: function is [Function:
    modifiers contains "native"
    /* uses of native on GWT applications are JSNI, not JNI */
    and not enclosingClass.supers contains [Class: name matches "com\.google\.gwt\..*"]
    and not enclosingClass.functions contains [Function:
        parameters contains [Variable:
           type.definition.enclosingClass.supers contains [Class: name matches "com\.google\.gwt\..*"]
        ]
        or contains [FunctionCall:
           function.enclosingClass.supers contains [Class: name matches "com\.google\.gwt\..*"]
        ]
    ]
    /* function is in a user-defined class */
    /* note: cannot use isBodyAvailable on the native function itself as it returns false (since there isn't really a body available anyway) */
    and enclosingClass is [Class: 
        /* note 2: this works on classes that ONLY specify native functions, due to the implicit default methods such as the constructor */
        functions contains [Function: isBodyAvailable]
    ]
]*

