Signature.getInstance("...withECDSA...")

CharacterizationRule.StructuralMatch:
FunctionCall fc:
   function is [Function:
       name matches "of|ofNullable"
       and enclosingClass.supers contains [Class:
           name == "java.util.Optional"
       ]
   ]
   and not arguments[0].possibleTypes contains [Type:
       name == "java.lang.String"
   ]

CharacterizationRule.Definition:
java.util / Vector.setElementAt(item, index) {
    controlflow:
        Escape(escapeArg = item)
}

java.util / Properties.setProperty(key, value) {
    controlflow:
        Escape(escapeArg = value)
}

java.util / Dictionary.put(key, value) {
    controlflow:
        Escape(escapeArg = value)
}

java.util / Map.put(key, value) {
    controlflow:
        Escape(escapeArg = value)
}

java.util / ListIterator.{add, set}(item) {
    controlflow:
        Escape(escapeArg = item)
}

java.util / List.{add, addAll, set}(index, item) {
    controlflow:
        Escape(escapeArg = item)
}

java.util / Collection.{add, addAll}(item) {
    controlflow:
        Escape(escapeArg = item)
}

java.util.jar / Attributes.putValue(key, value) {
    controlflow:
        Escape(escapeArg = value)
}

CharacterizationRule.StructuralMatch:
FunctionCall fc:
    function is [Function f:
        (constructor or name == "init^")
        and not isBodyAvailable
        and enclosingClass.supers contains [Class c:
            c.name == "java.util.Date"
        ]
    ]
    and instance is [Expression inst:]
    and arguments contains [Expression arg:]

FunctionCall fc:
    function is [Function f:
        (constructor or name == "init^")
        and not isBodyAvailable
        and enclosingClass.supers contains [Class c:
            c.name == "java.util.Map$Entry"
        ]
    ]
    and arguments[1] is [Expression arg1:]
    and instance is [Expression inst:]

FunctionCall fc:
    function is [Function f:
        (constructor or name == "init^")
        and not isBodyAvailable
        and enclosingClass.supers contains [Class c:
            c.name matches "java\.util\.(Collection|Deque|Enumeration|Formattable|Iterator|List|Map|Map\$Entry)"
        ]
    ]
    and arguments[0] is [Expression arg0:
        /* If arg0 is a number, it normally represents the size of the data structure */
         not arg0.type.name matches "int|long|float"
        and arg0.type.name != "java.util.Comparator"
    ]
    and instance is [Expression inst:]

