package java.util;

import java.util.Map;
import java.util.function.BiFunction;

public class FTFY_Map<K, V> implements java.util.Map<K, V> {
      public void compute(K key, java.util.function.BiFunction<? super K,? super V,? extends V> remappingFunction) {
          V oldValue = get(key);
          V newValue = remappingFunction.apply(key, oldValue);
          if (oldValue != null ) {
              if (newValue != null) put(key, newValue);
              else remove(key);
          } else {
              if (newValue != null) put(key, newValue);
              else return null;
          }
      }
}

