package java.util.stream;

import java.util.stream.Stream;
import java.util.function.BiFunction;
import java.util.function.BinaryOperator;
public class FTFY_Stream<U, T> implements java.util.stream.Stream<T> {
      public <U>U reduce(U identity, java.util.function.BiFunction<U,? super T,U> accumulator, java.util.function.BinaryOperator<U> combiner) {
          U result = identity;
          T[] array = (T[]) toArray();
          for (int i = 0; i < array.length; i++) {
              result = accumulator.apply(result, array[i]);
          }
          return combiner.apply(identity, result);
      }
}

